// MeshCore radio presets (the community-suggested LoRa settings of the MeshCore app, from api.meshcore.nz): a built-in table generated by
// tools/gen_meshcore_presets.py, and an optional newer list the user fetched (stored by the app, loaded here).
#pragma once
#include "dect2/mesh_proto.h"
#include <string>
#include <vector>

namespace dect2 {

struct MeshCorePreset {
    const char* title;     // "EU/UK (Narrow)"
    const char* region;    // "Europe", "North America", "Oceania", "South America", "Asia"
    double mhz;
    double bwKhz;
    int sf, cr;            // cr 5..8 = 4/5..4/8
    const char* note;      // "2B": the API's path-hash size, "" when it names none
};
extern const MeshCorePreset kMeshCorePresets[];
extern const int kMeshCorePresetCount;
extern const long long kMeshCorePresetsFetched;   // Unix time of the built-in table

struct MeshCorePresetEntry {
    std::string title, region, note;
    double mhz = 0, bwKhz = 0;
    int sf = 0, cr = 0;
};

// the region worked out from the title (same rule as the generator)
std::string meshCoreRegionOf(const std::string& title);
// "869.618 MHz / 62.5 kHz / SF8 / CR 4/8"
std::string meshCorePresetSummary(const MeshCorePresetEntry& p);
// The LoRa parameters the receiver needs (MeshCore: sync word 0x12, preamble 32 up to SF8 and 16 above); freqHz is the preset's frequency.
MeshLoraSettings meshCorePresetToLora(const MeshCorePresetEntry& p);
// The built-in table.
std::vector<MeshCorePresetEntry> meshCoreBuiltinPresets();
// Parses an api.meshcore.nz /config document (suggested_radio_settings.entries). False when it is not that document or holds no valid entry
// (frequency 400 - 1000 MHz, SF 5 - 12, CR 5 - 8, bandwidth 7.8 - 500 kHz); invalid entries are skipped.
bool parseMeshCoreConfig(const std::string& json, std::vector<MeshCorePresetEntry>& out);
// Loads a saved copy of the document; false (out untouched) when missing or malformed.
bool loadMeshCorePresetFile(const std::string& path, std::vector<MeshCorePresetEntry>& out);
// The list to use: the saved file when it loads and is newer than the built-in table, else the built-in one.
std::vector<MeshCorePresetEntry> meshCorePresets(const std::string& savedFile, bool* fromFile = nullptr);
std::vector<std::string> meshCoreRegions(const std::vector<MeshCorePresetEntry>& v);

// The bandwidths (Hz) a MeshCore setting may use here: 1 kHz to 1625 kHz (the standard SX126x / SX127x steps are 7.8 - 500 kHz, the
// SX128x 2.4 GHz ones 203.125 - 1625 kHz; other values only meet radios or SDRs set to exactly the same).
constexpr double kMeshCoreMinBwHz = 1e3, kMeshCoreMaxBwHz = 1625e3;
bool meshCoreBandwidthValid(double bwHz);
// A preset at another bandwidth: the same frequency, SF and CR, its title kept; preamble and LDRO follow the new bandwidth as
// meshCorePresetToLora decides them. bwHz outside the valid range leaves the preset's own.
MeshCorePresetEntry meshCorePresetWithBandwidth(const MeshCorePresetEntry& p, double bwHz);
// The LoRa settings to search for a set of presets: each preset as it is, then each one's frequency and SF again at every extra bandwidth
// (named "<title> @ <bw> kHz"). Settings already in the list (same frequency, SF and bandwidth) are not repeated; invalid bandwidths are skipped.
std::vector<MeshLoraSettings> meshCoreSearchSettings(const std::vector<MeshCorePresetEntry>& presets, const std::vector<double>& extraBwHz);

} // namespace dect2
